public class ShapeFactoryTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object roundedArea(String kind, double size) {
        try {
            Shape shape = ShapeFactory.create(kind, size);
            if (shape == null) return "null shape";
            return Math.round(shape.area() * 100.0) / 100.0;
        } catch (IllegalArgumentException e) {
            return "threw IllegalArgumentException";
        } catch (Exception e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("square side 3 (area to 2 dp)", 9.0, roundedArea("square", 3.0));
        check("square side 2.5 (area to 2 dp)", 6.25, roundedArea("square", 2.5));
        check("circle radius 1 (area to 2 dp)", 3.14, roundedArea("circle", 1.0));
        check("circle radius 2 (area to 2 dp)", 12.57, roundedArea("circle", 2.0));
        check("unknown kind throws", "threw IllegalArgumentException",
                roundedArea("triangle", 1.0));
        check("empty kind throws", "threw IllegalArgumentException",
                roundedArea("", 5.0));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

