interface Shape {
    double area();
}

public class ShapeFactory {

    public static Shape create(String kind, double size) {
        switch (kind) {
            case "circle":
                return () -> Math.PI * size * size;
            case "square":
                return () -> size * size;
            default:
                throw new IllegalArgumentException("Unknown shape kind: " + kind);
        }
    }
}
